t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "達圖爾的變形魔棒",
		["Insane druids"] = "發狂的德魯伊",
		["Lightforge Ingots"] = "光鑄鐵錠",
		["Melyria and {npc:3901}"] = "梅麗瑞亞與{npc:3901}",
