		["The wooden sign beside {npc:9997}"] = "{npc:9997}旁邊的木牌",
		["Western Pylon"] = "西部水晶塔",
		["Xiggs waits in the {object:32359}."] = "希格斯在{object:32359}等候。",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}：交給{zone:1447}的奧汀克，保留此任務",
