		["The next guide flies on from here to {zone:1454}."] = "下一份指南會從這裡飛往{zone:1454}。",
		["The salt flats"] = "鹽灘",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "前往藍寶石的路要穿過海岸北端沉沒的遺跡：從階梯走下坑洞。",
		["Thistlefur Hold"] = "薊皮熊怪的巢穴",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}，來自{npc:264081}",
		["{item:273658}, from {npc:264082}"] = "{item:273658}，來自{npc:264082}",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}，在升降梯頂端",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}，在雙足飛龍管理員旁",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}的下一個任務「聖火」在{zone:1456}完成，不在這條路線上。跳過。",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}是一隻大型夜刃豹，在戰歌伐木營地東南方的樹林中徘徊。她的爪子會開始下一個狩獵任務。",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717}會沿著海岸向北走到一座納迦火盆。熄滅火盆，然後在一波波納迦來襲時保護他，直到鞭笞者沃爾沙死亡。",
		["{npc:12717}: starts his escort at once"] = "{npc:12717}：會立刻開始他的護送任務",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}：只有在你帶著手冊書頁時",
		["{npc:12867} stands at the lumber camp. The night elf Outrunners stalk the woods south-east of it; they stealth, so watch for them."] = "{npc:12867}站在伐木營地。夜精靈的梣谷先驅者在營地東南方的樹林中潛行；他們會潛行，要留意。",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986}站在加拉克營地東邊的台地頂上。為了{quest:1149}，從他旁邊的木板盡頭走下去：你會安全落地。",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}：他的信要交給{zone:1418}的馬特克，約38級時",
		["{object:176344}, north-west camp"] = "{object:176344}，西北營地",
		["{object:176344}, south-east camp"] = "{object:176344}，東南營地",
		["{object:176344}, south-west camp"] = "{object:176344}，西南營地",
		["{object:19868} lies all over the flats north of the raceway. Scorpid Reavers and Sparkleshell Tortoises roam the north half, Salt Flats Scavengers circle overhead, and Saltstone Basilisks graze west of the track. The Crystalhides roam the middle of the flats and the Gazers (34-35, five levels above you: one at a time) the far south."] = "{object:19868}散落在賽道北邊的鹽灘各處。恐蠍劫掠者和鹽殼龜在北半部遊蕩，鹽湖食腐鷲在上空盤旋，鹽石蜥蜴在賽道西邊覓食。鹽石水晶蜥蜴在鹽灘中央遊蕩，鹽石凝視者（34-35級，比你高五級：一次拉一隻）在最南邊。",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
		["Clam beds"] = "蚌床",
		["Daggerspine naga"] = "刺脊納迦",
		["Daggerspine shore"] = "刺脊海岸",
		["Gizelton caravan"] = "基澤爾頓車隊",
		["Hearth back (or ride north if it is on cooldown)."] = "用爐石回去（如果在冷卻中就向北騎）。",
		["His next errand is not on this route."] = "他的下一個差事不在本路線上。",
		["Kolkar ears"] = "科卡爾耳朵",
		["Place the {object:1729} on the {object:1728} beside the inn"] = "把{object:1729}放在旅店旁的{object:1728}上",
		["Ride back south to the post."] = "向南騎回哨站。",
		["Ride north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat."] = "沿海岸向北騎。巨型軟殼蚌在淺水中，狂怒的暗礁蟹在海灘上走動；在背包中打開每個蚌取出蚌肉。",
		["Ride south-east to the post."] = "向東南騎到哨站。",
		["Ride south-west towards Shadowprey. The Gelkis centaurs (32-35) around their village are a good camp; fight them until level 32."] = "向西南往葬影村騎。吉爾吉斯半人馬（32-35級）在他們的村子周圍，是很好的刷怪點；打到32級。",
		["Shadowstalker scalp"] = "巡影者頭皮",
		["Shindigger keg"] = "鐵鏟酒桶",
		["Slitherblade Oracles"] = "滑刃智者",
		["Syndicate missives"] = "辛迪加信件",
		["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "道路西邊營地周圍的辛迪加劫匪和辛迪加竊賊（32-33級）身上帶著信件；約三分之一會掉落。",
		["Torn Fin beach"] = "碎鰭海灘",
		["Torn Fin murlocs"] = "碎鰭魚人",
		["Train"] = "訓練",
		["Train your new spells."] = "學習你的新法術。",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "對墓地裡的老邁的科多獸、瀕死的科多獸或{npc:4702}使用{npc:11596}的{item:13892}，把馴服的科多獸帶回給{npc:11596}。共五隻，一次一隻。",
		["Zeppelin tower"] = "飛艇塔",
		["for {npc:5901}: from Stranglethorn, next guide"] = "給{npc:5901}：來自荊棘谷，下一份指南",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}：拍賣場或鍊金術師，用於{quest:515}。",
		["{item:3703}, for {npc:2333}"] = "{item:3703}，給{npc:2333}",
		["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877}：給荊棘谷的{npc:715}",
		["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229}：給{zone:1413}，之後的路線",
		["{npc:4551}, the bat handler"] = "蝙蝠管理員{npc:4551}",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}，Grommash Hold，如果你帶著它",
		["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639}在The Drag等著；{npc:5640}站在城市西側的{object:172961}。天裔精靈：{npc:4949}在{object:172957}的Grommash Hold等著。",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}的下一個差事要你去對付一名帶著精英守衛的惡魔領主：跳過它。",
		["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "{npc:5641}的下一個{quest:1431}會白白把你派回{zone:1454}：不用理會。",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892}站在{object:172957}。",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}：你的{item:5178}",
		["{zone:1454} class quests"] = "{zone:1454}的職業任務",
} end)()
t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "向北回到營地。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Back to {object:3202}."] = "返回{object:3202}。",
		["Basilisks and the Bloodscalp village"] = "蜥蜴與血頂村莊",
		["Bloodscalp headhunters"] = "血頂獵頭者",
		["Bloodscalp ruins"] = "血頂遺跡",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "在巨魔東邊，深喉獵豹（37-38級）在攻擊之前都隱形潛行；荊棘谷雌虎在同一區域遊蕩，偶爾會掉落完好的尖牙。鉗嘴鱷魚沿著叢林西邊的河岸分布；把牠們的皮留給{npc:2495}。",
		["Elder tigers and Lashtail raptors"] = "老虎與鞭尾迅猛龍",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "沿著道路從{object:3202}向北走；奈辛瓦里的狩獵營地在河東北方的山丘上。從現在起，保留你拾取的每一頁{quest:338}：{npc:716}稍後會要。",
		["Follow the road south to {object:3202}."] = "沿著道路向南前往{object:3202}。",
		["Green Hills pages"] = "荊棘谷的青山書頁",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "向西經過營地。荊棘谷迅猛龍（33-34級）在林間空地獵食，血頂食人妖佔據海岸上的遺跡：每個血頂食人妖都可能掉落獠牙。他們極少數會掉落{item:4614}：如果掉了，閱讀它。",
		["Hearth to {object:3202}"] = "使用爐石前往{object:3202}",
		["Jungle Stalkers"] = "叢林捕獵者",
		["Lashtail raptors"] = "鞭尾迅猛龍",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "搭升降梯離開{zone:1458}，穿過廢墟走上飛艇塔；前往{object:3202}的飛艇在西南邊那座塔。",
		["Mistvale gorillas"] = "迷霧谷猩猩",
		["Mosh'Ogg camp"] = "莫什奧格營地",
		["Nesingwary's camp"] = "奈辛瓦里的營地",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "{item:2755}的每一頁從血頂和劈顱食人妖身上的掉落率約為1%；保留你拾取的每一頁，其餘的到拍賣場找。{npc:716}會在本指南稍後收下這些章節。",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "{item:2755}的每一頁從血頂和劈顱食人妖身上的掉落率約為1%；拿下掉落的書頁，其餘的到拍賣場看看。",
		["Raptors and the Bloodscalp trolls"] = "迅猛龍與血頂食人妖",
		["Ride back south to {object:3202}."] = "向南騎回{object:3202}。",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "向北騎過奈辛瓦里的營地前往湖邊。風險投資公司地質學家（34-36級）在湖西岸的營地工作；他們身上帶著打磨過的水晶。",
		["Shadowmaw jungle and the Snapjaw river"] = "深喉叢林與鉗嘴河",
		["Shadowmaw panthers"] = "深喉獵豹",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "荊棘谷猛虎和黑豹（32-33級）在營地東邊、沿著湖岸的山丘上遊蕩。",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "在{object:3202}西側的塔搭乘前往{zone:1454}的飛艇，並在繼續飛行前於城裡學習技能。",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "海岸村莊裡的血頂獵頭者（36-37級）身上帶著縮小的頭顱。",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "血頂食人妖佔據暗礁北邊海岸上的遺跡和更遠處的村莊；每一個都可能掉落{item:3915}。繼續拾取{quest:338}的書頁。",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "老年荊棘谷猛虎（34-35級）在營地西南方的山丘上遊蕩；鞭尾迅猛龍（35-36級）在更南邊、靠近{object:3202}處獵食。",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "叢林捕獵者（40-41級）在{object:3202}南邊的海岸獵食。牠們比你高很多：一次拉一隻，戰鬥之間休息。",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "鞭尾迅猛龍（35-36級）在{object:3202}東北方不遠處的叢林中獵食。",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "莫什奧格巨魔在{object:3202}東邊不遠處的山丘上紮營。擊殺一個莫什奧格蠻兵和一個莫什奧格巫醫（36-37級）；一次拉一隻。",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "深喉獵豹（37-38級）在莫什奧格山丘東邊以及往東北通往湖泊的叢林中潛行；牠們會從潛行中發動攻擊。沿途拾取你找到的每一頁荊棘谷的青山。",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "深喉獵豹要很久以後才會遇到，在{object:3202}附近",
		["The camp by the river"] = "河邊的營地",
		["The zeppelin lands at the tower on the west side of the camp."] = "飛艇降落在營地西側的塔。",
		["Tigers and panthers"] = "老虎與黑豹",
		["Venture Co. camp"] = "風險投資公司營地",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "向西經過營地，晶背蜥蜴（34-35級）坐在岩石上；再過去的村莊裡，每個血頂食人妖都可能掉落耳朵。",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "小荊棘谷猛虎在營地西邊徘徊，小獵豹在營地南邊和東邊。",
		["Young tigers and panthers"] = "小老虎與小獵豹",
		["Zeppelin to {object:3202}"] = "搭飛艇前往{object:3202}",
		["Zeppelin towers"] = "飛艇塔",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495}：先前收集的鉗嘴鱷魚皮",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}：給阿拉希，在路線稍後",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}：{npc:3527}和你的{item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "{npc:729}是一隻37級的老虎，在營地西南方的山頂上徘徊。",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "{npc:773}失蹤的獵人營地就是奈辛瓦里的營地：在帳篷之間走一走，調查就會完成。淡水鱷沿著營地下方的河邊趴著。",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Boulderfist camp"] = "石拳營地",
		["Coyotes and buzzards"] = "山狗與禿鷲",
		["Daggerspine shore"] = "刺脊海岸",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "護送教授下到岸邊。途中會有兩個刺脊納迦伏擊他：待在他身邊。",
		["Fleshstalker raptors"] = "獵獸龍",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "沿著道路向北走；{npc:4618}的營地就在路上。",
		["Greater Rock Elementals"] = "巨型石元素",
		["Highland raptors"] = "高地迅猛龍",
		["Into the {zone:1418}"] = "進入{zone:1418}",
		["Lesser Rock Elementals"] = "次級石元素",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "在落錘鎮東北方，枯鬚狗頭人在峽谷中挖礦；峽谷口的枯鬚狗頭人以及深處的枯鬚掘地工和枯鬚勘探員都會掉落密斯賴爾之塵。",
		["Ride north; the outer circle stands in the middle of the highlands."] = "向北騎；外圍法陣位於高地中央。",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "向西南騎往南岸哥布林的海灣。{npc:2766}在海灣上方的懸崖上守望。",
		["Rock Elementals"] = "石元素",
		["Stonevault troggs"] = "石窟穴居人",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "在{object:3202}西側的塔搭乘前往{zone:1454}的飛艇。",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "巨型石元素（42-44級，遠高於你）在西南方的溝壑中遊蕩；護腕大約每擊殺五隻掉落一次。一次拉一隻，戰鬥之間休息，或者不要去打。途中繼續擊殺你還需要的山狗和禿鷲。",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "辛迪加佔據西北方有圍牆的莊園及其農場；辛迪加路霸、辛迪加雇傭兵和辛迪加巡路者身上帶著血石護符。",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "枯木食人妖佔據東南山丘中的村莊。枯木擲斧者守著外圍的小屋；枯木巫醫和枯木獵頭者佔據村莊中心。",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "內圈法陣在西邊法陣的南邊、激流堡的東邊。",
		["The next guide heads into {zone:1445}."] = "下一份指南前往{zone:1445}。",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "位於道路東端的獸人要塞。雙足飛龍管理員{npc:2851}站在大門旁。",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "小型元素在{npc:2921}營地西邊的平地上漂移。本區每個石元素都可能掉落{npc:6868}要的石元素的碎片：保留它們。",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "這塊石頭的下一個任務需要對付42級精英弗茲魯克：先不要做。",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701}在峽谷的最深處。",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "趁你在{zone:1458}時學習：訓練師都在{object:36070}、{object:36073}和{object:36082}（聖騎士：{npc:260093}）。",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "在海灣西邊，刺脊襲擊者和刺脊巫師（38-40級）佔據海岸：一次拉一隻。兩艘沉船在外海的淺水中，海圖和航海日誌在船裡；寶石散落在沉船周圍的海底。",
		["Zeppelin to the {zone:1458}"] = "搭飛艇前往{zone:1458}",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["Zeppelin tower"] = "飛艇塔",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "給{zone:1443}的{npc:5395}，在下一份指南中",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}，給{zone:1445}的「沼澤之眼」加爾",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{npc:2771}的下一個{quest:678}要對付石拳精英：先不要做。",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}：只有在你帶著{item:2868}時（{skill:164}或拍賣場）",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661}沒有獵人或薩滿訓練師：改從同一座塔搭乘前往{zone:1454}的飛艇，在城裡學習，然後在{zone:1454}正門外的塔搭乘前往{zone:1458}的飛艇。",
		["{zone:1458} trainers"] = "{zone:1458}的訓練師",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "暗牙蜘蛛",
		["For {npc:2519} at {object:3202}, in the next guide"] = "交給{object:3202}的{npc:2519}，在下一份指南",
		["Hearth to Shadowprey"] = "用爐石回葬影村",
		["Kodo bones and ghosts"] = "科多獸骨與幽靈",
		["Maraudine totems"] = "瑪洛迪圖騰",
		["Mirefin murlocs"] = "黑鰭魚人",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "撿起散落在墳場各處的科多獸骨，並在骨頭之間使用{item:15848}：它吸引來的幽靈會掉落幽靈電漿。",
		["Ride back west to Brackenwall with the head."] = "帶著頭顱向西騎回蕨牆村。",
		["Ride north up the road to the hut by the road north of the graveyard."] = "沿著道路向北騎，前往墳場北邊路旁的小屋。",
		["Ride on south-west to Shadowprey."] = "繼續向西南騎往葬影村。",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "向西騎回沼澤另一頭。蕨牆村北邊山脊上的暗牙毒蜘蛛會掉落毒囊。塞拉摩間諜（35-36級）在同一片樹林中潛行：他們處於潛行狀態，要仔細看。",
		["Slitherblade coast"] = "滑刃海岸",
		["Stinky Ignatz"] = "伊格納茲",
		["Swamp Eye Jarl"] = "「沼澤之眼」加爾",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "在岔路往北走，前往巨魔村莊蕨牆村。",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "暗霧蜘蛛聚集在蕨牆村西北方的洞穴入口；每一種都會掉落眼球。",
		["The next guide takes you back to {zone:1434}."] = "下一份指南會帶你回到{zone:1434}。",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "僅限你帶著{item:3853}時（{skill:164}或拍賣場）",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}，在村莊南緣、道路進村的地方",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395}和{npc:5412}站在{npc:11596}營地西邊的哨站裡。",
		["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791}：上一份指南在這裡綁定爐石，所以這一步通常會立即完成",
		["{object:20985}, beside the manor"] = "{object:20985}，在莊園旁",
