} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "德萊尼水晶",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "沿海岸向南。納迦探險者在岸邊涉水，身上帶著蘆葦束；{object:759}就在他們東邊的丘陵中冒泡。",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "再往北，風險投資公司的哥布林在道路東邊的礦坑挖掘；礦工、工頭、勘探員和修理工都會掉落水晶。",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "把尖牙交給巫醫安巴格瓦並待在他身邊：他會召來三波猩猩，然後是{npc:1514}。一次對付一隻。",
		["Hearth to {object:3202}"] = "用爐石回到{object:3202}",
		["Into the {zone:1435}"] = "進入{zone:1435}",
		["Jungle stalkers"] = "叢林捕獵者",
		["Mistvale gorillas"] = "迷霧谷猩猩",
		["Naga shore and the {object:759}"] = "納迦海岸與{object:759}",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "在迷霧谷東北方，流亡者贊吉爾的追隨者在叢林中紮營；每一個都可能帶著混合物。",
		["Pirate ghosts"] = "海盜鬼魂",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "向北騎到風險投資公司礦坑東邊的劈顱食人妖廢墟；一次只拉一隻劈顱獵頭者或劈顱狂戰士。{npc:1059}守在西南方的廢墟，一堆祖瑪維顱骨堆在廢墟北側。每個劈顱食人妖都可能掉落獠牙或項鍊：項鍊最花時間，所以在廢墟北邊的劈顱戰士營地持續擊殺，直到收集完畢。",
		["Ride north up the road to the hunters' camp."] = "沿道路向北騎到獵人營地。",
		["Ride north up the road; the hunters camp on the hill above the river."] = "沿道路向北騎；獵人在河流上方的山丘上紮營。",
		["Ride north-west to {object:3202}."] = "向西北騎到{object:3202}。",
		["Ride west to {object:3202}."] = "向西騎到{object:3202}。",
		["Sawtooth crocolisks"] = "鹽齒鱷魚",
		["Sawtooth snappers"] = "鹽齒鉗嘴鱷",
		["Skullsplitter warriors"] = "劈顱戰士",
		["The Bloodsail ships"] = "血帆海盜船",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "猩猩在巫醫安巴格瓦周圍的山谷遊蕩。老邁的迷霧谷猩猩會掉落內臟；任何一隻都可能掉落尖牙。",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "最後一批顱骨堆在往西不遠的廢墟中，就在返回{object:3202}的路上。",
		["The next guide starts here and takes you to {zone:1446}."] = "下一份指南從這裡開始，帶你前往{zone:1446}。",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "下一批祖瑪維顱骨堆在劈顱戰士營地北邊不遠的小廢墟中。",
		["The snappers line the strand south of the post."] = "鹽齒鉗嘴鱷散布在哨站南邊的海灘上。",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "叢林捕獵者迅猛龍在{object:3202}南邊的叢林狩獵，一直延伸到西海岸。",
		["Venture Co. mine"] = "風險投資公司礦坑",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "遠征隊營地西邊，血頂酋長{npc:1061}和{npc:1062}一起站在祖昆達廢墟中。先清掉他們的守衛，再把他們拉過來。",
		["Zanzil's camps"] = "贊吉爾的營地",
		["Zul'Kunda"] = "祖昆達廢墟",
		["Zul'Mamwe"] = "祖瑪維廢墟",
		["for Stoley in {zone:1446}"] = "給{zone:1446}的斯杜雷",
		["for a later stop in the {zone:1435}"] = "留待之後在{zone:1435}的一站",
		["for later: the {zone:1425}, around level 48"] = "留待之後：{zone:1425}，約48級",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}，在{npc:2497}旁邊",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "東部廢土營地",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Grimtotem camp"] = "恐怖圖騰營地",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "繼續向西騎到海岸。海灘上的海灘龍蝦人先知和海灘利爪龍蝦人大約每擊殺四十隻會掉落一個OOX-22/FE定位器：如果掉了，使用它開始任務。",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "在豺狼人北邊，巨魔佔據山頂的前哨站；把巨魔法師拉過來打。鈷礦在前哨站周圍的土堆裡，卷軸就在前哨站裡的地上。",
		["Ride north-east to the goblin harbour on the coast."] = "向東北騎往海岸上的哥布林港口。",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "向西騎進{zone:1444}中部。擊殺一隻{npc:5308}，對牠的屍體使用{item:10699}，並擊殺升起的靈魂。",
		["Riding at 40"] = "40級騎術",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "騎術需要40級，費用100金；學會後會得到一匹坐騎。{npc:4752}在{object:172958}教導獸人，位於{npc:3362}的狼舍旁；目前沒有已知的天裔精靈騎術訓練師，所以天裔精靈也試試{npc:4752}。你種族的其他坐騎每匹20金：收藏品的「坐騎 · 40級」每一匹都有指南。",
		["Rogue Vale screechers"] = "遊蕩的山谷尖嘯者",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "沿著海岸往南，南海海盜佔據著海灣。{npc:7883}和被偷的貨物在海灣盡頭的碼頭上。任何海盜都可能掉落帽子，南海綁匪最常掉。",
		["Southern Gordunni ruins"] = "南部戈杜尼遺跡",
		["Southern Wastewander camps"] = "南部廢土營地",
		["Sprite darters and Woodpaw alphas"] = "小精龍與木爪突擊隊員",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "恐怖圖騰牛頭人在小精龍的樹林旁紮營；恐怖圖騰襲擊者、博學者和薩滿都帶著角。",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "木爪豺狼人在莫沙徹營地西北方的山丘上紮營；他們每一個都可能掉落鬃毛。",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "祖卡什蟲巢鑽進營地東南方的山丘裡；{quest:7731}在最深處的洞室等著。",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "戰鬥地圖在莫沙徹營地南邊的木爪營地裡。",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "小精龍在莫沙徹營地西邊的樹林上空飛舞；幾乎每一隻都會掉落翅膀。木爪突擊隊員帶領著西南方的營地：在一小時內殺掉他們。",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "前往{object:3202}的飛艇從{zone:1454}正門東北方不遠處的塔出發。",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "前往{zone:1454}的飛艇從{object:3202}旁的塔出發；它降落在{zone:1454}正門外不遠處。",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "狼：{npc:3362}，在{npc:4752}旁邊。",
		["Woodpaw battle map"] = "木爪戰鬥地圖",
		["Woodpaw north camp"] = "木爪北方營地",
		["Zeppelin to {object:3202}"] = "搭飛艇前往{object:3202}",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["Zeppelin tower"] = "飛艇塔",
		["for the {zone:1425}, around level 48"] = "給{zone:1425}，約48級時",
		["for {zone:1454}, around level 45"] = "給{zone:1454}，約45級時",
		["the {object:150075} in the square"] = "廣場上的{object:150075}",
		["water pouches in your bags"] = "背包裡的水袋",
		["{npc:3690}, riding trainer"] = "{npc:3690}，騎術訓練師",
		["{npc:4752}, riding trainer"] = "{npc:4752}，騎術訓練師",
		["{npc:4773}, riding trainer"] = "{npc:4773}，騎術訓練師",
		["{npc:7953}, riding trainer"] = "{npc:7953}，騎術訓練師",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}：給{zone:1454}，約45級時",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}：尖嘯者住在{zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}：從現在起一小時內",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "龍穴",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Forest walkers"] = "森林漫遊者",
		["Frayfeather hippogryphs"] = "亂羽角鷹獸",
		["Monstrous Crawlers"] = "巨型淤泥蟹",
		["Murlocs of the Misty Reed"] = "蘆葦崗哨的魚人",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "沿道路往西北，狂暴的怒痕雪人住在丘陵中的洞穴周圍。任何一隻也可能掉落{quest:7738}，它會開啟自己的任務。",
		["Northspring harpies"] = "北泉鷹身人",
		["Onyxia's eggs"] = "奧妮克希亞的蛋",
		["Rage Scar yetis"] = "狂暴的怒痕雪人",
		["Ride back north to Brackenwall."] = "向北騎回蕨牆村。",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "沿道路向西騎；卷軸在沼澤最西邊的水邊。",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "海元素和巨型海元素在碼頭周圍的海岸邊漂流。先用{item:18904}電擊巨人：縮小後就失去精英的力量。海岸巨人在水中涉行；大地行者和峭壁巨人在更北邊的山丘遊蕩。",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "山谷南邊，亂羽角鷹獸棲息在山坡上；幾乎每一隻都會掉落肌腱和金屬碎片。",
		["Sprite darters and forest walkers"] = "小精龍與森林漫遊者",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "沼澤魚人住在哨站南邊的海灘；沼澤噴墨魚人在哨站東邊的岸邊，沼澤食腐魚人在更西邊、西岸的小屋周圍。",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "巨型淤泥蟹在東岸的海灘上走動，數量稀少又分散：往南的路上看到就殺。",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "北泉鷹身人在最西北方的山脊上築巢。她們是48-50級，比你高幾級：北泉喚風者會治療，所以先殺她們，並一次只拉一隻。",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "同樣的魚人，再加上待在西岸小屋附近的沼澤魚人智者。",
		["The small Horde post on the southern shore."] = "南岸的小型部落哨站。",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "小精龍在營地西邊不遠的樹林上空飛舞，身上帶著{item:9589}；再往西一點的森林漫遊者身上帶著斷裂的原木。",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "前往{zone:1454}的飛艇從{object:3202}旁的塔出發；降落在{zone:1454}正門東北方不遠處。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["Zeppelin tower"] = "飛艇塔",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "之後給{zone:1425}的{npc:5598}，約48級",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "之後在本指南中用於{zone:1445}的{object:2555}",
		["for the {zone:1425} owlbeasts, around level 48"] = "之後給{zone:1425}的梟獸，約48級",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500}是精英：建議組隊。把他打到認輸，然後向{npc:4501}報告。",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}：之後給{zone:1454}的{npc:7010}，約50級",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}，然後是{object:172960}和{object:172961}。",
		["{quest:7738}, a rare drop"] = "{quest:7738}，稀有掉落",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Dark Iron Lookouts"] = "黑鐵哨兵",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "更往南，謝申克的勘探設備在一個森提帕爾蟲巢的入口處。",
		["Greater Lava Spiders"] = "巨型熔岩蜘蛛",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "重型作戰傀儡在卡拉然下方的大熔爐巡邏，會掉落油；在牠們之間飄移的熔岩元素和熾熱元素會掉落核心。黑鐵工頭和黑鐵奴隸販子在小路上驅趕奴隸；奴隸販子可能掉落{item:11818}：保留它。",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "他的下一個請求需要精英教徒身上的{item:10552}：別管它。",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "僅限持有{item:11818}時：向東回到挖掘場的{object:173265}。",
		["Scrimshank's gear"] = "謝申克的設備",
		["South down the road again."] = "再次沿著道路往南走。",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "在加基森東南方，廢土強盜在沙丘間紮營；{npc:7847}站在東邊的營地裡。",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "黑鐵哨兵站在大熔爐南邊哨塔周圍的山脊上；大約十分之一帶有{item:18960}。",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "黑鐵鍛造師在大熔爐中央操作熔爐；一半帶有{item:10551}，十分之一帶有{item:18959}。奴隸工、奴隸販子和工頭也帶著匕首。",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "巨型熔岩蜘蛛在峽谷西南部的高地和熔岩池周圍遊蕩。",
		["The Steamsmiths' furnaces"] = "鍛造師的熔爐",
		["The {object:179827} board"] = "{object:179827}告示板",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "在加基森西邊，於食人妖營地的水池旁使用{item:8584}。",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "營地西邊的山谷滿是仙人掌生物；只有灌木露水收集者帶著露水腺體。{zone:1446}的大部分怪物都可能掉落OOX-17/TN定位器，但很稀有：看到就保留。",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "往西，森提帕爾蟲子在牠們的蟲巢周圍聚集；牠們都會掉落肢體。",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}生長在{zone:1425}，大約48級",
		["the {object:150075} in the square"] = "廣場上的{object:150075}",
		["the {object:173265}"] = "{object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}，稀有掉落",
		["{item:8623}, a rare drop"] = "{item:8623}，稀有掉落",
		["{npc:5955}'s escort"] = "護送{npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在雙足飛龍管理員旁邊",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "道路東邊，灰鬃野豬和格朗特在紅石蜥蜴旁的山坡上拱土。遠離更南邊52級的地獄野豬。",
		["East of the village, the violet flower grows in the hills."] = "村子東邊的丘陵上長著紫色水生菇。",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "沿道路向東穿過{zone:1425}，前往東海岸的食人妖村落。",
		["Grind to 48"] = "刷到48級",
		["Highvale"] = "高原精靈",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "沿海岸向北，{npc:14731}的野餐籃在小島上；由一個{npc:14748}看守。",
		["OOX-09/HL"] = "OOX-09/HL",
		["Only if you are not level 48 yet."] = "只有在你還沒48級時。",
		["Ride back north to the bloodmages."] = "向北騎回血法師那裡。",
		["Saltwater Snapjaws"] = "海水鉗嘴龜",
		["Silvermane Howlers"] = "銀鬃嗥狼",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "小屋南邊，枯木食人妖佔據他們的村落。每一隻身上都帶著頭骨：收集二十個後，使用{item:15002}製作尼姆布亞的長矛，然後插在村子裡。",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "往西南，銀鬃嗥狼在枯木村落東邊的丘陵遊蕩。",
		["The Vilebranch temples"] = "邪枝神廟",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "大海龜在村子北邊的海灘上爬行。{npc:2491}的波特酒瓶也在這些海灘上，但他的任務不在本路線上。鉗嘴龜偶爾會掉落OOX-09/HL的求救信標：留著它。",
		["The bloodmages"] = "血法師",
		["The central hills"] = "中部丘陵",
		["The eastern slopes"] = "東坡",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "五個任務需要相同的材料：一趟全部收集。道路西邊，{npc:5982}禿鷲、饑餓的彎牙土狼、厚甲毒刺蠍和死眼蜥蜴共同分布在丘陵上。",
		["The northern beasts"] = "北方的野獸",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "他們的後續任務要你再交一次同樣的材料換取增益物品，不給經驗值：不用理會。",
		["Vilebranch soothsayers"] = "邪枝占卜者",
		["Vulture hills"] = "禿鷲丘陵",
		["for {npc:6986} in {zone:1454}, around level 50"] = "之後給{zone:1454}的{npc:6986}，約50級",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "之後給{zone:1458}的{npc:7825}，約50級",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "在{zone:1419}北部丘陵刷{npc:5982}",
		["{item:8704}, a rare drop"] = "{item:8704}，稀有掉落",
		["{npc:14731}'s lunch"] = "{npc:14731}的午餐",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}：給{zone:1456}，約50級",
		["{npc:7801}'s camp"] = "{npc:7801}的營地",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}，{object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "向東北回到{npc:8420}處。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "沿著道路向南走；蜥蜴在叢林中段、道路東邊的岩石上曬太陽。牠們的碎片很常掉落。",
		["Frayfeather Hippogryphs"] = "亂羽角鷹獸",
		["Highborne and Haldarr satyrs"] = "精靈貴族與哈達爾薩特",
		["Ironjaw Basilisks"] = "鐵齶蜥蜴",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "保留要交給{npc:4046}、{npc:8659}和{npc:6522}的貨物：你稍後會經過{zone:1456}、{zone:1454}和{zone:1458}。",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "保留{quest:3444}：{npc:7771}的箱子要在下次造訪時打開。",
		["Only once all three robots are home"] = "三個機器人都回家後才能做",
		["Ride into {zone:1447}"] = "騎進{zone:1447}",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "向西南騎往遺跡。四塊石板在遺跡之間，由惡鞭納迦看守；任何惡鞭海妖或惡鞭侍從都可能帶著{npc:8420}的符文。",
		["Sea elementals"] = "海元素",
		["Sprite Darters"] = "小精龍",
		["Take the zeppelin back to {zone:1454}."] = "搭飛艇回到{zone:1454}。",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "精靈貴族的鬼魂在神殿北邊的遺跡中出沒；哈達爾薩特在更北邊一點紮營。",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "大地行者和峭壁巨人在碼頭北邊的山丘上遊蕩。先用{item:18904}電擊每一隻：縮小後牠們就不再是精英。每個被縮小的巨人都會掉落殘渣；也對牠的屍體使用靈魂精華容器。",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "海元素和巨型海元素在碼頭周圍的岸邊沖刷。",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "血精靈的營地就在{npc:8420}南邊。他的四件裝備在營地周圍的箱子裡。",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "精靈龍在營地西邊的樹林中飛舞。對你殺死的每一隻使用容器。",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "角鷹獸在營地西南方的山丘上築巢。殺一隻，然後對牠的屍體使用靈魂精華容器。",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "樹人在營地和{zone:1444}中部之間的林間道路上遊蕩；數量不多，沿著小路找找。",
		["The {object:2076} beside {npc:2519}"] = "{npc:2519}旁邊的{object:2076}",
		["To {object:3202}"] = "前往{object:3202}",
		["Undamaged Hippogryph Feathers"] = "完整的角鷹獸羽毛",
		["Wandering Forest Walkers"] = "森林漫遊者",
		["Zapped giants"] = "被縮小的巨人",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}，在城裡",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}：熊在{zone:1448}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825}站在{object:36082}。",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}的焦油和匹斯特蘇格的樣本都來自{zone:1449}。",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在雙足飛龍管理員旁",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}，在營地東緣：沒有經驗值，只能傳送到艾薩拉的高塔",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，{object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}在下一份指南中收集；{npc:4046}的報酬稍後交回給{npc:8587}。",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Black Broodlings"] = "黑色小龍",
		["Bloodpetal Flayers"] = "血瓣花掠奪者",
		["Cross the south of the crater to the pylon on the western cliffs."] = "穿過環形山南部，前往西邊懸崖上的水晶塔。",
		["Darrowshire Spirits"] = "達隆郡居民的靈魂",
		["Eastern Pylon"] = "東部水晶塔",
		["Escort {npc:9999}"] = "護送{npc:9999}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "沿著懸崖向南前往火腹巨魔的山丘{quest:3821}。{npc:9136}的遺骸在山腳下。",
		["Free Darrowshire Spirits: talk to them"] = "釋放達隆郡居民的靈魂：和它們交談",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "從現在起，拾取沿途經過的每一個能量水晶（藍、綠、紅、黃）和每一堆{quest:3761}：共25份土壤，20份給哈繆爾，5份給匹斯特蘇格。",
		["Gorillas"] = "猩猩",
		["Into the {zone:1427}"] = "進入{zone:1427}",
		["Into {zone:1449}"] = "進入{zone:1449}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "保留誘餌：{npc:9684}是56級，第二圈路線會經過牠的巢穴。",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "保留{npc:9118}的{quest:4147}和{npc:8737}的信，留給之後的指南。",
		["Lar'korwi Mates"] = "拉克維的配偶",
		["Lashers and Threshers"] = "血瓣花鞭笞者與猛擊者",
		["North of Torwa, a dead Threshadon lies by the water."] = "在托爾瓦北邊，一頭死去的蛇頸龍躺在水邊。",
		["Northern Pylon"] = "北部水晶塔",
		["Out of the refuge"] = "離開避難營",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "匹斯特蘇格的下一個任務需要擊殺精英首領{npc:10041}。跳過。",
		["Power Crystals and soil"] = "能量水晶與土壤",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "沿著環形山東側往下騎到東邊懸崖上的水晶塔。",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "沿著東側向北騎。血瓣花鞭笞者和血瓣花猛擊者佈滿叢林。",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "沿著西側懸崖向西南騎。{npc:9167}在西側上空飛行，血瓣花捕獸者生長在同一片叢林裡。",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "向西騎往挖掘場。{npc:7039}魔像（53級）在周圍走動，常掉落碎片；{quest:4296}立在挖掘場中央的索瑞森矮人之間。抄錄它。",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "在溫泉南邊，劍龍在吃草，恐龍骨頭由牠們掉落或散落在地上；附近的雙帆龍帶著{npc:9998}要的鱗片。暴掠龍在西南方成群狩獵：牠們的爪子交給{npc:8659}，偶爾還會帶著被撕破的日記（稀有掉落：只有拿到時才接它的任務）。避開格魯夫，一頭57級的劍龍。",
		["Stegodons and ravasaurs"] = "劍龍與暴掠龍",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "從德靈頓旁邊的箱子拿一個{object:176092}，用於{quest:5096}，在回程時完成。裝備{quest:5401}：只有穿戴時才會掉落天譴石。",
		["Termite mounds"] = "白蟻丘",
		["Thaurissan dig site"] = "索瑞森挖掘場",
		["The Gorishi hive"] = "格里什蟲巢",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "拉克維的配偶在{npc:9619}西北方的叢林中徘徊。",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "洋娃娃的腦袋和左右兩側散落在{npc:10926}周圍的房子裡；在背包中將它們組合起來。",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "探險隊的箱子在東部叢林中一處廢棄的營地裡。",
		["The expedition's lost equipment lies in the south-west jungle."] = "探險隊遺失的設備在西南方的叢林裡。",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "猩猩住在東北方的高地上。不要進入最深的洞穴：{npc:9622}住在那裡。",
		["The next guide starts here, at the chapel's flight master."] = "下一份指南從這裡開始，在禮拜堂的飛行管理員處。",
		["The pylon stands on the slope east of the refuge."] = "水晶塔位於避難營東邊的山坡上。",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "木筏在東南方湖泊的岸邊；小包就在旁邊的水裡。",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "異種蠍巢穴佔滿環形山南部。格里什異種蠍和格里什工蠍會掉落香味腺體；在第一個巢室內的卵堆上使用採集瓶。底部的格里什蜂后是精英首領：不要進入她的巢室。{npc:9166}在蟲巢上方的懸崖築巢；牠們的鱗片交給{npc:9998}。",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "焦油坑就在避難營南邊。焦油獸、焦油潛伏者和焦油爬行者會掉落{item:11834}。",
		["The wooden sign beside {npc:9997}"] = "{npc:9997}旁邊的木牌",
		["Use the Mangled Journal to start it"] = "使用被撕破的日記開始任務",
		["Western Pylon"] = "西部水晶塔",
		["Western jungle"] = "西部叢林",
		["{item:11116}, a rare drop"] = "{item:11116}，稀有掉落",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}要你去找{zone:1452}的{npc:9298}：保留此任務。",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}，{object:36078}，在蝙蝠管理員旁邊",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}，{object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}，皇家藥劑師協會：瓶子稍後在{zone:1447}裝滿",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}，在洞穴深處",
		["{npc:9618}, just outside"] = "{npc:9618}，就在外面",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}在環形山的東南角紮營。",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619}現在要{npc:9622}的毛皮，在東北方的洞穴裡：跳過。",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623}接著會要一個{item:10561}，這是{skill:202}物品。除非你有，否則跳過。",
		["{npc:9623}, the robot on the plateau"] = "{npc:9623}，高地上的機器人",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "{npc:9684}的巢穴就在水晶塔南邊。在那裡使用{npc:9619}的誘餌；{npc:9684}是56級且攻擊力強，滿血再開始。",
		["{npc:9998}, at the entrance"] = "{npc:9998}，在入口",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避難營入口",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999}坐在山脊上，迷路又筋疲力盡。",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}在{quest:3821}的洞穴和礦坑隧道中走動；如果他不在，就清掉入口周圍的巨魔，直到他回來。",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
